const   workerId   =   createServerlessWorkerId  ()  ;
const   worker   =   new   ServerlessWorker  (  "./worker.js"  ,   workerId)  ;
conn  .  port  .  postMessage  ({ action  :   'greet'  ,   data  :   'foo'   })  ;
}
}  ;


```


